//! Gold: `dw-controller` is 1:1 with the live `factory_control.py`
//! reference across the unattended-run lifecycle.
//!
//! `tests/fixtures/gold/factory_battery_v1.json` was generated by
//! `scripts/gold_factory_battery.py`: 27 steps driving the LIVE Python
//! factory — discovery with stability windows, quarantine, duplicate
//! detection, queue registration + idempotency, claim/renew/complete/fail,
//! lease-expiry recovery, validation errors, the event-immutability
//! trigger, status/summaries, and normalized table dumps.
//!
//! Normalization is mirrored exactly: observation ids → `src#N` (path
//! order), event ids → `evt#N` (ledger order), lease tokens → `<TOKEN>`,
//! device/inode/mtime → 0, root → `$ROOT`, and event payload digests
//! recomputed over the normalized payload — which makes each digest a live
//! differential of the payload contents across both engines.

#![allow(
    clippy::expect_used,
    clippy::cast_possible_truncation,
    clippy::needless_pass_by_ref_mut,
    clippy::similar_names,
    clippy::option_option,
    clippy::needless_pass_by_value,
    clippy::items_after_statements,
    clippy::redundant_clone,
    clippy::needless_continue,
    clippy::cloned_ref_to_slice_refs,
    clippy::ptr_arg,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    clippy::too_many_lines,
    clippy::doc_markdown,
    clippy::panic,
    reason = "gold tests assert on their own fixtures"
)]

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use serde_json::{json, Map, Value};

use dw_controller::{FactoryError, FactoryState};

fn gold_path() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("tests/fixtures/gold").is_dir() {
        assert!(dir.pop(), "could not locate tests/fixtures/gold");
    }
    dir.join("tests/fixtures/gold/factory_battery_v1.json")
}

fn gold() -> Value {
    serde_json::from_str(&std::fs::read_to_string(gold_path()).unwrap()).unwrap()
}

/// The generator's `Normalizer`, mirrored.
struct Normalizer {
    resolved: String,
    root: String,
    source_map: BTreeMap<String, String>,
    event_map: BTreeMap<String, String>,
}

#[allow(
    clippy::should_implement_trait,
    clippy::needless_pass_by_value,
    reason = "normalizer twin"
)]
impl Normalizer {
    fn new(root: &Path) -> Self {
        Self {
            resolved: std::fs::canonicalize(root)
                .unwrap_or_else(|_| root.to_path_buf())
                .display()
                .to_string(),
            root: root.display().to_string(),
            source_map: BTreeMap::new(),
            event_map: BTreeMap::new(),
        }
    }

    fn text(&self, value: &str) -> String {
        if value.starts_with("source-") && value.len() == 39 {
            if let Some(mapped) = self.source_map.get(value) {
                return mapped.clone();
            }
        }
        if value.starts_with("factory-event-") {
            if let Some(mapped) = self.event_map.get(value) {
                return mapped.clone();
            }
        }
        value
            .replace(&self.resolved, "$ROOT")
            .replace(&self.root, "$ROOT")
    }

    fn remember_source(&mut self, value: &str) -> String {
        if value.starts_with("source-") && value.len() == 39 {
            let next = self.source_map.len() + 1;
            self.source_map
                .entry(value.to_string())
                .or_insert_with(|| format!("src#{next}"))
                .clone()
        } else {
            self.text(value)
        }
    }

    fn remember_event(&mut self, value: &str) -> String {
        if value.starts_with("factory-event-") {
            let next = self.event_map.len() + 1;
            self.event_map
                .entry(value.to_string())
                .or_insert_with(|| format!("evt#{next}"))
                .clone()
        } else {
            self.text(value)
        }
    }

    fn token(&self, value: &str) -> String {
        // secrets.token_urlsafe(32): 43 url-safe chars, padding stripped.
        if value.len() == 43
            && value
                .bytes()
                .all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_')
        {
            "<TOKEN>".to_string()
        } else {
            self.text(value)
        }
    }
}

fn payload_sha(payload: &Value) -> String {
    let bytes = dw_extract::canonical::canonical_json(payload).expect("payload canonicalizes");
    dw_extract::sha256::sha256_hex(&bytes)
}

fn write_tree(root: &Path, files: &[Value]) {
    for entry in files {
        let target = root.join(entry["rel"].as_str().unwrap());
        std::fs::create_dir_all(target.parent().unwrap()).unwrap();
        if let Some(link_to) = entry.get("symlink_to") {
            std::os::unix::fs::symlink(root.join(link_to.as_str().unwrap()), &target).unwrap();
        } else {
            let bytes: Vec<u8> = entry["bytes"]
                .as_array()
                .unwrap()
                .iter()
                .map(|b| b.as_u64().unwrap() as u8)
                .collect();
            std::fs::write(&target, bytes).unwrap();
        }
    }
}

fn err_string(error: &FactoryError, normalizer: &Normalizer) -> String {
    let text = format!("{}: {}", error.kind(), error);
    text.replace(&normalizer.resolved, "$ROOT")
        .replace(&normalizer.root, "$ROOT")
}

/// Full table dump in the generator's shape.
fn dump(state: &FactoryState, normalizer: &mut Normalizer) -> Value {
    let connection = state.connect().unwrap();
    // Seed the source-id map in path order, exactly like the generator.
    {
        let mut statement = connection
            .prepare(
                "SELECT observation_id FROM factory_source_observations
                 ORDER BY source_path, first_seen_at",
            )
            .unwrap();
        let ids: Vec<String> = statement
            .query_map([], |row| row.get(0))
            .unwrap()
            .flatten()
            .collect();
        for id in ids {
            normalizer.remember_source(&id);
        }
    }
    let mut observations: Vec<Value> = Vec::new();
    {
        let mut statement = connection
            .prepare(
                "SELECT observation_id, source_path, device, inode, byte_size,
                        mtime_ns, first_seen_at, stable_after_at, last_seen_at,
                        status, sha256, canonical_observation_id, reason,
                        updated_at
                 FROM factory_source_observations
                 ORDER BY source_path, first_seen_at",
            )
            .unwrap();
        let rows = statement
            .query_map([], |row| {
                Ok(json!({
                    "observation_id": row.get::<_, String>(0)?,
                    "source_path": row.get::<_, String>(1)?,
                    "device": row.get::<_, i64>(2)?,
                    "inode": row.get::<_, i64>(3)?,
                    "byte_size": row.get::<_, i64>(4)?,
                    "mtime_ns": row.get::<_, i64>(5)?,
                    "first_seen_at": row.get::<_, String>(6)?,
                    "stable_after_at": row.get::<_, String>(7)?,
                    "last_seen_at": row.get::<_, String>(8)?,
                    "status": row.get::<_, String>(9)?,
                    "sha256": row.get::<_, Option<String>>(10)?,
                    "canonical_observation_id":
                        row.get::<_, Option<String>>(11)?,
                    "reason": row.get::<_, Option<String>>(12)?,
                    "updated_at": row.get::<_, String>(13)?,
                }))
            })
            .unwrap();
        for row in rows.flatten() {
            observations.push(normalize_observation(row, normalizer));
        }
    }
    let mut chunks: Vec<Value> = Vec::new();
    {
        let mut statement = connection
            .prepare(
                "SELECT chunk_id, queue_path, queue_sha256,
                        queue_evidence_sha256, offset, item_count,
                        output_directory, status, attempt, max_attempts,
                        available_at, lease_node, lease_token,
                        lease_expires_at, output_manifest_sha256, error,
                        created_at, updated_at
                 FROM factory_chunks
                 ORDER BY created_at, offset, chunk_id",
            )
            .unwrap();
        let rows = statement
            .query_map([], |row| {
                Ok(json!({
                    "chunk_id": row.get::<_, String>(0)?,
                    "queue_path": row.get::<_, String>(1)?,
                    "queue_sha256": row.get::<_, String>(2)?,
                    "queue_evidence_sha256": row.get::<_, String>(3)?,
                    "offset": row.get::<_, i64>(4)?,
                    "item_count": row.get::<_, i64>(5)?,
                    "output_directory": row.get::<_, String>(6)?,
                    "status": row.get::<_, String>(7)?,
                    "attempt": row.get::<_, i64>(8)?,
                    "max_attempts": row.get::<_, i64>(9)?,
                    "available_at": row.get::<_, String>(10)?,
                    "lease_node": row.get::<_, Option<String>>(11)?,
                    "lease_token": row.get::<_, Option<String>>(12)?,
                    "lease_expires_at": row.get::<_, Option<String>>(13)?,
                    "output_manifest_sha256":
                        row.get::<_, Option<String>>(14)?,
                    "error": row.get::<_, Option<String>>(15)?,
                    "created_at": row.get::<_, String>(16)?,
                    "updated_at": row.get::<_, String>(17)?,
                }))
            })
            .unwrap();
        for row in rows.flatten() {
            chunks.push(normalize_chunk(row, normalizer));
        }
    }
    // Seed event ids in ledger order.
    let mut events: Vec<Value> = Vec::new();
    {
        let mut statement = connection
            .prepare("SELECT rowid FROM factory_events ORDER BY created_at, rowid")
            .unwrap();
        let rowids: Vec<i64> = statement
            .query_map([], |row| row.get(0))
            .unwrap()
            .flatten()
            .collect();
        for rowid in rowids {
            let event_id: String = connection
                .query_row(
                    "SELECT event_id FROM factory_events WHERE rowid = ?1",
                    [rowid],
                    |row| row.get(0),
                )
                .unwrap();
            normalizer.remember_event(&event_id);
        }
    }
    {
        let mut statement = connection
            .prepare(
                "SELECT event_id, event_type, subject_id, payload_json,
                        payload_sha256, created_at
                 FROM factory_events ORDER BY created_at, rowid",
            )
            .unwrap();
        let rows = statement
            .query_map([], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, String>(2)?,
                    row.get::<_, String>(3)?,
                    row.get::<_, String>(5)?,
                ))
            })
            .unwrap();
        for (event_id, event_type, subject_id, payload_json, created_at) in rows.flatten() {
            let mut payload: Value = serde_json::from_str(&payload_json).unwrap();
            if let Some(map) = payload.as_object_mut() {
                if let Some(mtime) = map.get_mut("mtime_ns") {
                    *mtime = json!(0);
                }
                for (_, value) in map.iter_mut() {
                    if let Value::String(text) = value {
                        *value = json!(normalizer.text(text));
                    }
                }
            }
            let sha = payload_sha(&payload);
            events.push(json!({
                "event_id": normalizer.remember_event(&event_id),
                "event_type": event_type,
                "subject_id": normalizer.text(&subject_id),
                "payload_json": payload,
                "payload_sha256": sha,
                "created_at": created_at,
            }));
        }
    }
    json!({
        "observations": observations,
        "chunks": chunks,
        "events": events,
        "batches": [],
    })
}

fn normalize_observation(mut row: Value, normalizer: &Normalizer) -> Value {
    let map = row.as_object_mut().unwrap();
    for key in ["device", "inode", "mtime_ns"] {
        map.insert(key.to_string(), json!(0));
    }
    let id = map
        .get("observation_id")
        .and_then(Value::as_str)
        .unwrap()
        .to_string();
    map.insert("observation_id".into(), json!(normalizer.text(&id)));
    if let Some(Value::String(path)) = map.get("source_path") {
        let path = path.clone();
        map.insert("source_path".into(), json!(normalizer.text(&path)));
    }
    for key in ["sha256", "canonical_observation_id", "reason"] {
        if let Some(Value::String(text)) = map.get(key) {
            let text = text.clone();
            map.insert(key.to_string(), json!(normalizer.text(&text)));
        }
    }
    row
}

fn normalize_chunk(mut row: Value, normalizer: &Normalizer) -> Value {
    let map = row.as_object_mut().unwrap();
    if let Some(Value::String(token)) = map.get("lease_token") {
        let token = token.clone();
        map.insert("lease_token".into(), json!(normalizer.token(&token)));
    }
    for key in ["queue_path", "output_directory"] {
        if let Some(Value::String(text)) = map.get(key) {
            let text = text.clone();
            map.insert(key.to_string(), json!(normalizer.text(&text)));
        }
    }
    row
}

fn lease_dict(lease: Option<&dw_controller::ChunkLease>, normalizer: &Normalizer) -> Value {
    match lease {
        None => Value::Null,
        Some(lease) => json!({
            "chunk_id": normalizer.text(&lease.chunk_id),
            "node": lease.node,
            "attempt": lease.attempt,
            "lease_token": normalizer.token(&lease.lease_token),
            "lease_expires_at": lease.lease_expires_at,
            "queue_path": normalizer.text(&lease.queue_path.display().to_string()),
            "queue_sha256": lease.queue_sha256,
            "offset": lease.offset,
            "item_count": lease.item_count,
            "output_directory":
                normalizer.text(&lease.output_directory.display().to_string()),
        }),
    }
}

fn expect_err(step: &str, error: FactoryError, want: &Value, normalizer: &Normalizer) {
    assert_eq!(
        json!(err_string(&error, normalizer)),
        want["error"],
        "step {step}: error string"
    );
}

#[test]
fn battery_matches_the_live_reference() {
    let g = gold();
    let root = std::env::temp_dir().join(format!("gold_factory_rust_{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(&root).unwrap();
    write_tree(&root, g["files"].as_array().unwrap());

    let state = FactoryState::open(&root.join("state")).expect("state opens");
    let mut normalizer = Normalizer::new(&root);
    let ev = root.join("ev");
    let t = |offset: i64| -> String {
        let base = "2026-10-14T01:00:00+00:00";
        let micros = dw_controller::ts::parse(base).unwrap() + offset * 1_000_000;
        dw_controller::ts::format(micros)
    };

    let mut actual: Vec<Value> = Vec::new();
    fn record(step: &str, fields: Vec<(&str, Value)>) -> Value {
        let mut map = Map::new();
        map.insert("step".into(), json!(step));
        for (key, value) in fields {
            map.insert(key.to_string(), value);
        }
        Value::Object(map)
    }

    // ── discovery lifecycle ──────────────────────────────────────────
    let report = state
        .discover_pdfs(std::slice::from_ref(&ev), 60, Some(&t(0)))
        .unwrap();
    actual.push(record(
        "discover_t0",
        vec![("report", serde_json::to_value(&report).unwrap())],
    ));
    let report = state
        .discover_pdfs(std::slice::from_ref(&ev), 60, Some(&t(30)))
        .unwrap();
    actual.push(record(
        "discover_t30",
        vec![("report", serde_json::to_value(&report).unwrap())],
    ));
    let report = state
        .discover_pdfs(std::slice::from_ref(&ev), 60, Some(&t(61)))
        .unwrap();
    actual.push(record(
        "discover_t61",
        vec![("report", serde_json::to_value(&report).unwrap())],
    ));

    // ── queue registration ───────────────────────────────────────────
    let queue_bytes = std::fs::read(root.join("queue.json")).unwrap();
    let queue_sha = dw_extract::sha256::sha256_hex(&queue_bytes);
    let chunk_ids = state
        .register_queue(
            &root.join("queue.json"),
            &root.join("out"),
            2,
            3,
            0,
            Some(&t(0)),
        )
        .unwrap();
    actual.push(record(
        "register_queue",
        vec![("chunk_ids", json!(chunk_ids))],
    ));
    let again = state
        .register_queue(
            &root.join("queue.json"),
            &root.join("out"),
            2,
            3,
            0,
            Some(&t(0)),
        )
        .unwrap();
    actual.push(record(
        "register_queue_idempotent",
        vec![("chunk_ids", json!(again))],
    ));

    // ── lease lifecycle ──────────────────────────────────────────────
    let t1: i64 = 1000;
    let lease1 = state.claim_chunk("asus2", 60, Some(&t(t1))).unwrap();
    let lease2 = state.claim_chunk("asus2", 1800, Some(&t(t1))).unwrap();
    let lease3 = state.claim_chunk("asus2", 60, Some(&t(t1))).unwrap();
    let fourth = state.claim_chunk("asus2", 60, Some(&t(t1))).unwrap();
    actual.push(record(
        "claims_t1",
        vec![
            ("lease1", lease_dict(lease1.as_ref(), &normalizer)),
            ("lease2", lease_dict(lease2.as_ref(), &normalizer)),
            ("lease3", lease_dict(lease3.as_ref(), &normalizer)),
            ("fourth", lease_dict(fourth.as_ref(), &normalizer)),
        ],
    ));

    let renewed = state
        .renew_chunk(lease1.as_ref().unwrap(), 60, Some(&t(t1 + 30)))
        .unwrap();
    actual.push(record("renew_lease1", vec![("expires", json!(renewed))]));

    let failed_status = state
        .fail_chunk(
            lease2.as_ref().unwrap(),
            "transient worker oom",
            false,
            30,
            Some(&t(t1 + 10)),
        )
        .unwrap();
    actual.push(record(
        "fail_lease2_retry",
        vec![("status", json!(failed_status))],
    ));
    let blocked = state.claim_chunk("asus3", 60, Some(&t(t1 + 20))).unwrap();
    actual.push(record(
        "claim_blocked",
        vec![("lease", lease_dict(blocked.as_ref(), &normalizer))],
    ));
    let reclaimer = state.claim_chunk("asus3", 60, Some(&t(t1 + 40))).unwrap();
    actual.push(record(
        "claim_retry_available",
        vec![("lease", lease_dict(reclaimer.as_ref(), &normalizer))],
    ));
    let terminal_status = state
        .fail_chunk(
            reclaimer.as_ref().unwrap(),
            "terminal extraction failure",
            true,
            30,
            Some(&t(t1 + 50)),
        )
        .unwrap();
    actual.push(record(
        "fail_terminal",
        vec![("status", json!(terminal_status))],
    ));

    // complete chunk 1 against its sealed output directory (already
    // materialised by write_tree from the fixture's manifest bytes).
    let completed_sha = state
        .complete_chunk(lease1.as_ref().unwrap(), Some(&t(t1 + 60)))
        .unwrap();
    actual.push(record(
        "complete_lease1",
        vec![("manifest_sha", json!(completed_sha))],
    ));
    let repeated_sha = state
        .complete_chunk(lease1.as_ref().unwrap(), Some(&t(t1 + 61)))
        .unwrap();
    actual.push(record(
        "complete_lease1_idempotent",
        vec![("manifest_sha", json!(repeated_sha))],
    ));

    let recovered = state.recover_expired(Some(&t(t1 + 200))).unwrap();
    actual.push(record(
        "recover_expired",
        vec![("recovered", json!(recovered))],
    ));
    let reclaimed = state.claim_chunk("asus4", 60, Some(&t(t1 + 201))).unwrap();
    actual.push(record(
        "claim_after_recover",
        vec![("lease", lease_dict(reclaimed.as_ref(), &normalizer))],
    ));

    match state.renew_chunk(lease1.as_ref().unwrap(), 60, Some(&t(t1 + 300))) {
        Ok(_) => panic!("expected stale lease error"),
        Err(error) => actual.push(record(
            "renew_completed_chunk",
            vec![("error", json!(err_string(&error, &normalizer)))],
        )),
    }

    // ── validation errors ────────────────────────────────────────────
    let expected = g["steps"].as_array().unwrap();
    {
        let want = expected
            .iter()
            .find(|s| s["step"] == "error_blank_node")
            .unwrap();
        let error = state.claim_chunk("  ", 60, Some(&t(t1))).unwrap_err();
        expect_err("blank_node", error, want, &normalizer);
        let got = record("error_blank_node", vec![("error", json!(()))]);
        actual.push(rewrite_error(got, want, &normalizer));
    }
    {
        let want = expected
            .iter()
            .find(|s| s["step"] == "error_short_lease")
            .unwrap();
        let error = state.claim_chunk("n1", 10, Some(&t(t1))).unwrap_err();
        expect_err("short_lease", error, want, &normalizer);
        let got = record("error_short_lease", vec![("error", json!(()))]);
        actual.push(rewrite_error(got, want, &normalizer));
    }
    {
        let want = expected
            .iter()
            .find(|s| s["step"] == "error_bad_stability")
            .unwrap();
        let error = state
            .discover_pdfs(std::slice::from_ref(&ev), -1, Some(&t(0)))
            .unwrap_err();
        expect_err("bad_stability", error, want, &normalizer);
        let got = record("error_bad_stability", vec![("error", json!(()))]);
        actual.push(rewrite_error(got, want, &normalizer));
    }
    {
        let want = expected
            .iter()
            .find(|s| s["step"] == "error_bad_chunk_size")
            .unwrap();
        let error = state
            .register_queue(
                &root.join("queue.json"),
                &root.join("o2"),
                0,
                3,
                0,
                Some(&t(0)),
            )
            .unwrap_err();
        expect_err("bad_chunk_size", error, want, &normalizer);
        let got = record("error_bad_chunk_size", vec![("error", json!(()))]);
        actual.push(rewrite_error(got, want, &normalizer));
    }
    {
        let want = expected
            .iter()
            .find(|s| s["step"] == "error_untrimmed_error")
            .unwrap();
        let error = state
            .fail_chunk(
                lease3.as_ref().unwrap(),
                " padded ",
                false,
                30,
                Some(&t(t1)),
            )
            .unwrap_err();
        expect_err("untrimmed_error", error, want, &normalizer);
        let got = record("error_untrimmed_error", vec![("error", json!(()))]);
        actual.push(rewrite_error(got, want, &normalizer));
    }
    {
        let want = expected
            .iter()
            .find(|s| s["step"] == "error_missing_root")
            .unwrap();
        let error = state
            .discover_pdfs(&[root.join("nope")], 1, Some(&t(0)))
            .unwrap_err();
        expect_err("missing_root", error, want, &normalizer);
        let got = record("error_missing_root", vec![("error", json!(()))]);
        actual.push(rewrite_error(got, want, &normalizer));
    }

    // ── event immutability ───────────────────────────────────────────
    {
        let connection = state.connect().unwrap();
        let error = connection
            .execute("UPDATE factory_events SET event_type = 'tampered'", [])
            .unwrap_err();
        let message = error.to_string();
        drop(connection);
        let want = expected
            .iter()
            .find(|s| s["step"] == "events_immutable")
            .unwrap();
        assert!(
            message.contains(want["contains"].as_str().unwrap()),
            "immutability trigger: {message}"
        );
        actual.push(record(
            "events_immutable",
            vec![("contains", json!(message))],
        ));
    }

    // ── visibility ───────────────────────────────────────────────────
    {
        let mut status = state.status().unwrap();
        status.as_object_mut().unwrap().remove("created_at");
        actual.push(record("status", vec![("status", status)]));
    }
    {
        let summary = state.queue_chunk_summary(&queue_sha).unwrap();
        actual.push(record("queue_summary", vec![("summary", summary)]));
    }
    {
        let paths: Vec<Value> = state
            .completed_bundle_paths(&queue_sha)
            .unwrap()
            .iter()
            .map(|path| json!(normalizer.text(&path.display().to_string())))
            .collect();
        actual.push(record("completed_paths", vec![("paths", json!(paths))]));
    }
    actual.push(record(
        "tables",
        vec![("dump", dump(&state, &mut normalizer))],
    ));

    // ── compare every step in order ──────────────────────────────────
    let expected_steps = g["steps"].as_array().unwrap();
    assert_eq!(actual.len(), expected_steps.len(), "step count");
    for (index, (got, want)) in actual.iter().zip(expected_steps).enumerate() {
        let step = want["step"].as_str().unwrap();
        assert_eq!(got["step"], want["step"], "step {index}: name");
        match step {
            "events_immutable" => continue, // contains-check above
            _ => assert_eq!(got, want, "step {index} ({step})"),
        }
    }

    let _ = std::fs::remove_dir_all(&root);
}

/// Replace the placeholder error slot with the fixture's recorded string
/// (already verified verbatim by `expect_err`).
fn rewrite_error(mut got: Value, want: &Value, _normalizer: &Normalizer) -> Value {
    got.as_object_mut()
        .unwrap()
        .insert("error".into(), want["error"].clone());
    got
}
